import ast, re

def main(input):
    task = input.get("task") or {}
    inp = task.get("inputs") or {}
    files = task.get("files") or {}
    module_path = inp.get("module_path") or ""
    source = inp.get("source")
    if not source and module_path and module_path in files:
        source = files[module_path]
    if not source:
        for k, v in files.items():
            if k.endswith(".py") and "test" not in k.lower():
                source, module_path = v, module_path or k
                break
    source = source or ""
    mod = (module_path.rsplit("/", 1)[-1] or "module.py")[:-3] if module_path.endswith(".py") else (module_path or "module")
    tests = inp.get("visible_tests") or ""
    if not tests:
        for k, v in files.items():
            if "test" in k.lower() and k.endswith(".py"):
                tests = v
                break

    def get(*keys):
        for k in keys:
            if inp.get(k):
                return inp[k]
        return ""

    known = {"module_path", "source", "tests_path", "visible_tests", "bug_report", "design_notes",
             "changelog", "ci_log", "service_log"}
    parts = []
    for title, val in (("docs/DESIGN.md (authoritative)", get("design_notes")),
                       ("BUG_REPORT.md (user reports; may be wrong or incomplete)", get("bug_report")),
                       ("CHANGELOG.md", get("changelog")),
                       ("CI last run", get("ci_log"))):
        if val:
            parts.append("=== " + title + " ===\n" + val.strip())
    for k, v in inp.items():
        if k not in known and isinstance(v, str) and v.strip():
            parts.append("=== " + k + " ===\n" + v.strip()[:6000])
    docs = "\n\n".join(parts)

    log = get("service_log")
    names = set()
    try:
        tree = ast.parse(source)
        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                names.add(node.name)
                if isinstance(node, ast.ClassDef):
                    for sub in node.body:
                        if isinstance(sub, ast.FunctionDef):
                            names.add(sub.name)
    except Exception:
        pass
    keep = []
    for line in log.splitlines():
        if mod in line or "->" in line or "Traceback" in line or "Error" in line or any(
                re.search(r"\b" + re.escape(n) + r"\(", line) for n in names if len(n) > 3):
            line = re.sub(r"^\S+T\S+Z\s+", "", line)
            keep.append(line)
    log_txt = "\n".join(keep)
    if len(log_txt) > 14000:
        log_txt = log_txt[:14000] + "\n...(truncated)"

    numbered = "\n".join("%4d| %s" % (i + 1, l) for i, l in enumerate(source.splitlines()))
    return {"module": mod, "module_path": module_path, "source": source, "numbered": numbered,
            "tests": tests, "docs": docs, "log": log_txt or "(no log lines)"}

import ast, difflib, sys, types, signal, traceback

def api(src):
    out = {}
    tree = ast.parse(src)
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
            out[node.name] = ast.dump(node.args)
        elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            out[node.name] = "class"
            for sub in node.body:
                if isinstance(sub, (ast.FunctionDef, ast.AsyncFunctionDef)) and (not sub.name.startswith("_") or sub.name.startswith("__")):
                    out[node.name + "." + sub.name] = ast.dump(sub.args)
    return out

def apply_edit(src, find, repl):
    if not find:
        return None, "empty find"
    c = src.count(find)
    if c == 1:
        return src.replace(find, repl, 1), None
    if c > 1:
        return None, "find text occurs %d times; include more context" % c
    # tolerant: match on stripped lines
    flines = [l.strip() for l in find.strip("\n").splitlines()]
    slines = src.splitlines(keepends=True)
    hits = []
    for i in range(len(slines) - len(flines) + 1):
        if all(slines[i + k].strip() == flines[k] for k in range(len(flines))):
            hits.append(i)
    if len(hits) != 1:
        return None, "find text not found exactly once (%d fuzzy matches)" % len(hits)
    i = hits[0]
    orig_block = slines[i:i + len(flines)]
    ind_src = orig_block[0][:len(orig_block[0]) - len(orig_block[0].lstrip())]
    rlines = repl.strip("\n").splitlines()
    first = next((l for l in find.strip("\n").splitlines() if l.strip()), "")
    ind_find = first[:len(first) - len(first.lstrip())]
    fixed = []
    for l in rlines:
        if l.startswith(ind_find):
            fixed.append(ind_src + l[len(ind_find):])
        else:
            fixed.append(l)
    nl = "\n" if orig_block[-1].endswith("\n") else ""
    new = "".join(slines[:i]) + "\n".join(fixed) + nl + "".join(slines[i + len(flines):])
    return new, None

class _Raises:
    def __init__(self, exc, match=None):
        self.exc, self.match = exc, match
    def __enter__(self):
        return self
    def __exit__(self, et, ev, tb):
        if et is None:
            raise AssertionError("DID NOT RAISE %r" % (self.exc,))
        if not issubclass(et, self.exc):
            return False
        if self.match:
            import re
            if not re.search(self.match, str(ev)):
                raise AssertionError("exception message %r does not match %r" % (str(ev), self.match))
        self.value = ev
        return True

def make_pytest():
    m = types.ModuleType("pytest")
    def raises(exc, *args, match=None, **kw):
        if args:
            fn = args[0]
            try:
                fn(*args[1:], **kw)
            except exc:
                return
            raise AssertionError("DID NOT RAISE")
        return _Raises(exc, match)
    class Approx:
        def __init__(self, v, rel=1e-6, abs=1e-12):
            self.v, self.rel, self.abs = v, rel, abs
        def __eq__(self, o):
            try:
                if isinstance(self.v, (list, tuple)):
                    return len(o) == len(self.v) and all(Approx(a, self.rel, self.abs) == b for a, b in zip(self.v, o))
                if isinstance(self.v, dict):
                    return set(o) == set(self.v) and all(Approx(self.v[k], self.rel, self.abs) == o[k] for k in self.v)
                return abs(o - self.v) <= max(self.rel * abs(self.v), self.abs)
            except Exception:
                return False
        def __repr__(self):
            return "approx(%r)" % (self.v,)
    def approx(v, rel=1e-6, abs=1e-12):
        return Approx(v, rel, abs)
    class Mark:
        def __getattr__(self, name):
            def deco(*a, **k):
                def wrap(fn):
                    marks = getattr(fn, "_marks", [])
                    marks.append((name, a, k))
                    fn._marks = marks
                    return fn
                if name != "parametrize" and len(a) == 1 and callable(a[0]) and not k:
                    return wrap(a[0])
                return wrap
            return deco
    def fixture(*a, **k):
        if a and callable(a[0]):
            return a[0]
        return lambda f: f
    m.raises, m.approx, m.mark, m.fixture = raises, approx, Mark(), fixture
    return m

def _timeout(signum, frame):
    raise TimeoutError("test timed out (possible infinite loop)")

def run_tests(src, mod, tests):
    if not tests.strip():
        return 0, []
    failures = []
    module = types.ModuleType(mod)
    try:
        exec(compile(src, mod + ".py", "exec"), module.__dict__)
    except Exception as e:
        return 0, ["module failed to import: %r" % (e,)]
    sys.modules[mod] = module
    sys.modules["pytest"] = make_pytest()
    ns = {"__name__": "test_module"}
    try:
        exec(compile(tests, "test_module.py", "exec"), ns)
    except Exception as e:
        return 0, ["test file failed to import: %r" % (e,)]
    count = 0
    for name, fn in list(ns.items()):
        if not (name.startswith("test") and callable(fn)):
            continue
        cases = [((), {})]
        for (mname, a, k) in getattr(fn, "_marks", []):
            if mname == "parametrize" and len(a) >= 2:
                argn = [x.strip() for x in a[0].split(",")] if isinstance(a[0], str) else list(a[0])
                new = []
                for args, kw in cases:
                    for vals in a[1]:
                        if len(argn) == 1:
                            vals = (vals,)
                        d = dict(kw)
                        d.update(dict(zip(argn, vals)))
                        new.append((args, d))
                cases = new
        for args, kw in cases:
            count += 1
            try:
                try:
                    signal.signal(signal.SIGALRM, _timeout)
                    signal.alarm(5)
                except Exception:
                    pass
                fn(*args, **kw)
            except BaseException as e:
                tb = traceback.extract_tb(e.__traceback__)
                line = ""
                tlines = tests.splitlines()
                for fr in tb:
                    if fr.filename == "test_module.py" and fr.lineno and fr.lineno <= len(tlines):
                        line = tlines[fr.lineno - 1].strip()
                failures.append("%s%s: %s: %s | at: %s" % (name, ("[%s]" % kw) if kw else "", type(e).__name__, str(e)[:300], line[:300]))
            finally:
                try:
                    signal.alarm(0)
                except Exception:
                    pass
    return count, failures

def main(input):
    base = input["base"]
    original = input["original"]
    mod = input["module"]
    tests = input.get("tests") or ""
    edits = (input.get("fix") or {}).get("edits") or []
    src = base
    applied, rejected = [], []
    for e in edits:
        find, repl = e.get("find", ""), e.get("replace", "")
        if find == repl:
            continue
        new, err = apply_edit(src, find, repl)
        if err:
            rejected.append({"find": find[:400], "error": err})
            continue
        try:
            ast.parse(new)
        except SyntaxError as se:
            rejected.append({"find": find[:400], "error": "edit causes SyntaxError: %s" % se})
            continue
        src = new
        applied.append(e.get("function", ""))
    problems = []
    try:
        a0, a1 = api(original), api(src)
        for k, v in a0.items():
            if k not in a1:
                problems.append("public name removed: " + k)
            elif a1[k] != v:
                problems.append("signature changed: " + k)
    except SyntaxError as se:
        problems.append("SyntaxError: %s" % se)
    ntests, failures = run_tests(src, mod, tests)
    diff = "".join(difflib.unified_diff(original.splitlines(True), src.splitlines(True), "a/" + mod + ".py", "b/" + mod + ".py", n=2))
    return {"source": src, "applied": applied, "rejected": rejected, "problems": problems,
            "ntests": ntests, "failures": failures, "ok": not problems and not failures and not rejected,
            "diff": diff or "(no changes)",
            "report": "applied edits: %d; rejected edits: %s; api problems: %s; visible tests run: %d; failures: %s" % (
                len(applied), rejected or "none", problems or "none", ntests, failures or "none")}

def main(input):
    s = input['s']
    return {'numbered': '\n'.join('%4d| %s' % (i + 1, l) for i, l in enumerate(s.splitlines()))}

