def main(input):
    s1, s2 = input["s1"], input.get("s2")
    pick = s1
    if s2 and not s2.get("problems"):
        # prefer the reviewed version unless it is clearly worse on visible tests
        if len(s2.get("failures") or []) <= len(s1.get("failures") or []) or s1.get("problems"):
            pick = s2
    return {"patched_source": pick["source"]}
